<script setup lang="ts">import{ref}from'vue';import{onLoad,onPullDownRefresh}from'@dcloudio/uni-app';import WareState from'@/shared/components/WareState.vue';import WarePhoneLink from'@/shared/components/WarePhoneLink.vue';import{agriMaterialApi}from'../../api/agri-material.api';const id=ref(''),data=ref<any>(),loading=ref(true),error=ref('');async function load(){loading.value=true;error.value='';try{data.value=await agriMaterialApi.detail(id.value)}catch(e){error.value=e instanceof Error?e.message:'订单详情加载失败'}finally{loading.value=false;uni.stopPullDownRefresh()}}onLoad(q=>{id.value=String(q?.id||'');load()});onPullDownRefresh(load);</script>
<template><view class="page"><WareState v-if="loading" type="loading" title="正在加载订单详情"/><WareState v-else-if="error" type="error" title="加载失败" :description="error" action-label="重试" @action="load"/><template v-else-if="data"><view class="info"><view class="head"><b>{{data.order.orderId}}</b><span :class="`s${data.order.orderStatus}`">{{data.order.statusLabel}}</span></view><view><text>基地</text><b>{{data.order.baseName}}</b></view><view><text>购买供应商</text><b>{{data.order.buySupplierName}}</b></view><view><text>农资供应商</text><b>{{data.order.peasantSupplierName}}</b></view><view><text>收件人</text><b>{{data.order.receiveName}}</b></view><view><text>收件电话</text><WarePhoneLink :phone="data.order.receiveTel" compact/></view><view><text>收件地址</text><b>{{data.order.receiveAddress}}</b></view><view><text>下单时间</text><b>{{data.order.createTime}}</b></view><view v-if="data.order.shipTime"><text>发货时间</text><b>{{data.order.shipTime}}</b></view><view v-if="data.order.completeTime"><text>签收时间</text><b>{{data.order.completeTime}}</b></view><view v-if="data.order.completeUserName"><text>签收人</text><b>{{data.order.completeUserName}}</b></view><view v-if="data.order.buyerMemo"><text>备注</text><b>{{data.order.buyerMemo}}</b></view></view><view class="table-head"><text>商品/规格</text><text>数量</text><text>金额</text></view><view v-for="x in data.items" :key="x.id" class="item"><view><b>{{x.goodsInfo}}</b><small>{{x.skuInfo}}</small></view><b>{{x.quantity}}</b><b>¥{{x.totalPrice.toFixed(2)}}</b></view></template></view></template>
<style scoped>.page{min-height:100vh;padding:18rpx 20rpx;background:var(--wms-background)}.info{padding:17rpx;background:#fff}.head,.info>view{display:flex;align-items:flex-start;justify-content:space-between;gap:15rpx;margin-top:11rpx}.head{margin:0 0 15rpx;padding-bottom:12rpx;border-bottom:1rpx solid var(--wms-border)}.head>b{font-size:24rpx}.head span{padding:3rpx 8rpx;border-radius:5rpx;font-size:17rpx}.s1{background:#f0f2f2}.s2{background:#fff1da;color:#9b5c00}.s3{background:var(--wms-surface-soft);color:var(--wms-success)}.info>view>text{width:110rpx;flex:none;color:var(--wms-text-secondary);font-size:19rpx}.info>view>b{font-size:20rpx;text-align:right}.table-head,.item{display:grid;grid-template-columns:minmax(0,1.6fr) 70rpx 100rpx;gap:8rpx;align-items:center}.table-head{margin-top:14rpx;padding:12rpx;background:var(--wms-primary-700);color:#fff;font-size:18rpx}.item{margin-top:5rpx;padding:13rpx;background:#fff;font-size:19rpx}.item small{display:block;margin-top:5rpx;color:var(--wms-text-secondary);font-size:17rpx}</style>
